-- Tienda Latam
-- Script base para PostgreSQL / pgAdmin
-- Nota: se usa GENERATED BY DEFAULT AS IDENTITY para permitir
-- importar IDs existentes desde archivos CSV.

--Categoria_id,Nombre_Categoria,Descripcion
CREATE TABLE categorias (
    categoria_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_categoria VARCHAR(100) NOT NULL,
    descripcion TEXT
);

--Pais_id,Codigo_Pais,Nombre_Pais,Continente
CREATE TABLE paises (
    pais_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Codigo_Pais VARCHAR(10),
    nombre_pais VARCHAR(100) NOT NULL,
    Continente VARCHAR(20)
);

--Tipo_Cliente_ID,Nombre_Tipo,Descripcion
CREATE TABLE tipos_clientes (
    tipo_cliente_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_tipo VARCHAR(100) NOT NULL,
    descripcion TEXT
);

--Sucursal_ID,Nombre_Sucursal,Ciudad,Pais_ID,Direccion_Completa,Activo
CREATE TABLE sucursales (
    sucursal_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_sucursal VARCHAR(100) NOT NULL,
    ciudad VARCHAR(100),
    pais_id INTEGER,
    Direccion_Completa  VARCHAR(40),
    Activo boolean DEFAULT true,
    CONSTRAINT fk_sucursal_pais
        FOREIGN KEY (pais_id) REFERENCES paises(pais_id)
);

--Empleado_ID,Nombre,Apellido,Email,Sucursal_ID,FechaIngreso,telefono,Cargo,Activo
CREATE TABLE empleados (
    empleado_id INT PRIMARY KEY,
    Nombre VARCHAR(100) NOT NULL,
    Apellido VARCHAR(100) NOT NULL,
    Email VARCHAR(150) UNIQUE NOT NULL,
    SucursalID INT NOT NULL,
    FechaIngreso DATE NOT NULL,
    Cargo VARCHAR(100),
    Activo BOOLEAN NOT NULL,

    CONSTRAINT fk_empleado_sucursal
        FOREIGN KEY (sucursalID)
        REFERENCES Sucursales(sucursal_id)
);

--Cliente_ID,Nombre,Apellido,Email,Telefono,Pais_ID,Ciudad,TipoClienteID,FechaRegistro,Activo
--Cliente_ID,Nombre_cliente,Apellido_cliente,Email,Telefono,Pais_ID,Ciudad,Tipo_Cliente_ID,FechaRegistro,Activo
CREATE TABLE clientes (
    cliente_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_cliente VARCHAR(150) NOT NULL,
    apellido_cliente VARCHAR(150) NOT NULL,
    email VARCHAR(150),
    telefono VARCHAR(50),
    pais_id INTEGER,
 --   direccion VARCHAR(255),
    ciudad VARCHAR(100),
    tipo_cliente_id INTEGER,
    FechaRegistro date DEFAULT CURRENT_DATE,
    Activo boolean DEFAULT true,
    CONSTRAINT fk_cliente_pais
        FOREIGN KEY (pais_id) REFERENCES paises(pais_id),
    CONSTRAINT fk_cliente_tipo
        FOREIGN KEY (tipo_cliente_id) REFERENCES tipos_clientes(tipo_cliente_id)
);

--ProductoID,Codigo_Producto,Nombre_Producto,Categoria_ID,Precio,Stock,Descripcion,Activo
--Producto_ID,Codigo_Producto,Nombre_Producto,Categoria_ID,Precio,Stock,Descripcion,Activo
CREATE TABLE productos (
    producto_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Codigo_Producto VARCHAR(10),
    nombre_producto VARCHAR(150) NOT NULL,
    categoria_id INTEGER,
    precio NUMERIC(10,2) NOT NULL,
    stock INTEGER DEFAULT 0,
    descripcion TEXT,
    Activo boolean DEFAULT true,
    CONSTRAINT fk_producto_categoria
        FOREIGN KEY (categoria_id) REFERENCES categorias(categoria_id)
);

--PedidoID,ClienteID,SucursalID,EmpleadoID,FechaPedido,Estado,Total,Notas
--Pedido_ID,Cliente_ID,Sucursal_ID,Empleado_ID,Fecha_Pedido,Estado,Total,Notas
CREATE TABLE pedidos (
    pedido_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INTEGER NOT NULL,
    sucursal_id INTEGER,
    empleado_id INTEGER,
    fecha_pedido DATE NOT NULL,
    estado VARCHAR(50),
    total NUMERIC(12,2),
    notas text,
    CONSTRAINT fk_pedido_cliente
        FOREIGN KEY (cliente_id) REFERENCES clientes(cliente_id),
    CONSTRAINT fk_pedido_empleado
        FOREIGN KEY (empleado_id) REFERENCES empleados(empleado_id),
    CONSTRAINT fk_pedido_sucursal
        FOREIGN KEY (sucursal_id) REFERENCES sucursales(sucursal_id)
);

--DetalleID,PedidoID,ProductoID,Cantidad,PrecioUnitario
--Detalle_pedido_ID,Pedido_ID,Producto_ID,Cantidad,Precio_Unitario,descuento
CREATE TABLE detalles_pedidos (
    detalle_pedido_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pedido_id INTEGER NOT NULL,
    producto_id INTEGER NOT NULL,
    cantidad INTEGER NOT NULL,
    precio_unitario NUMERIC(10,2) NOT NULL,
    -- descuento NUMERIC(5,2) DEFAULT 0,
    CONSTRAINT fk_detalle_pedido
        FOREIGN KEY (pedido_id) REFERENCES pedidos(pedido_id),
    CONSTRAINT fk_detalle_producto
        FOREIGN KEY (producto_id) REFERENCES productos(producto_id)
);


-- Verificación
SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'public'
ORDER BY table_name;